//! Differential tests for `s2::CellUnion` against the C++ reference implementation
//! (google/s2geometry).
//!
//! The vectors in `data/cpp_cellunion_vectors.csv` are generated by
//! `tools/refgen-cpp/generate_cellunion` using the C++ S2 library as an *independent*
//! oracle (specs/002-formal-verify-cell-union, research R13). They cover normalisation,
//! denormalisation, the set operations and union queries, range construction, the leaf
//! count, and the binary encoding. Several of these operations are beyond the Kani proofs
//! (`difference` and the range constructors are tool-limit exclusions), so these tests are
//! their parity evidence. Ids are exact `u64` values written as 16 hex digits, so every
//! comparison is exact.

use s2rst::s2::CellId;
use s2rst::s2::CellUnion;
use s2rst::s2::coords::Level;
use s2rst::s2::encoding::{S2Decode, S2Encode};

const CSV: &str = include_str!("data/cpp_cellunion_vectors.csv");

/// Lines of a named `# SECTION` (stops at the next `#`/blank line).
fn section_lines(name: &str) -> Vec<&'static str> {
    let header = format!("# {name}");
    let mut in_section = false;
    let mut lines = Vec::new();
    for line in CSV.lines() {
        if line == header {
            in_section = true;
            continue;
        }
        if in_section {
            if line.starts_with('#') || line.is_empty() {
                break;
            }
            lines.push(line);
        }
    }
    assert!(!lines.is_empty(), "no {name} vectors");
    lines
}

fn fields(line: &str) -> Vec<&str> {
    line.split(',').collect()
}

fn hex64(s: &str) -> u64 {
    u64::from_str_radix(s, 16).unwrap_or_else(|e| panic!("bad id {s:?}: {e}"))
}

/// A `;`-separated id list; the empty field is the empty list.
fn ids(s: &str) -> Vec<CellId> {
    if s.is_empty() {
        Vec::new()
    } else {
        s.split(';').map(|x| CellId(hex64(x))).collect()
    }
}

fn bytes(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}

fn flag(s: &str) -> bool {
    match s {
        "0" => false,
        "1" => true,
        _ => panic!("bad flag {s:?}"),
    }
}

/// `CellUnion::from_cell_ids` must match C++ `S2CellUnion(ids)` (normalisation).
#[test]
fn normalize_matches_cpp() {
    for line in section_lines("CELLUNION_NORMALIZE") {
        let f = fields(line);
        let got = CellUnion::from_cell_ids(ids(f[0]));
        assert_eq!(
            got.cell_ids(),
            &ids(f[1])[..],
            "normalize disagrees with C++ on: {line}"
        );
    }
}

/// `denormalize` must match C++ `Denormalize`, including the clamp to level 30 when rounding
/// up would pass it (FR-015).
#[test]
fn denormalize_matches_cpp() {
    for line in section_lines("CELLUNION_DENORMALIZE") {
        let f = fields(line);
        let (min_level, level_mod): (u8, u8) = (f[1].parse().unwrap(), f[2].parse().unwrap());
        let got = CellUnion::from_verbatim(ids(f[0])).denormalize(Level::new(min_level), level_mod);
        assert_eq!(
            got.cell_ids(),
            &ids(f[3])[..],
            "denormalize disagrees with C++ on: {line}"
        );
    }
}

/// `union`, `intersection`, `difference`, `contains_union` and `intersects_union` must match
/// C++ `Union`, `Intersection`, `Difference`, `Contains` and `Intersects` on normalised
/// unions.
#[test]
fn set_ops_match_cpp() {
    for line in section_lines("CELLUNION_SETOPS") {
        let f = fields(line);
        let a = CellUnion::from_verbatim(ids(f[0]));
        let b = CellUnion::from_verbatim(ids(f[1]));
        assert_eq!(a.union(&b).cell_ids(), &ids(f[2])[..], "union: {line}");
        assert_eq!(
            a.intersection(&b).cell_ids(),
            &ids(f[3])[..],
            "intersection: {line}"
        );
        assert_eq!(
            a.difference(&b).cell_ids(),
            &ids(f[4])[..],
            "difference: {line}"
        );
        assert_eq!(a.contains_union(&b), flag(f[5]), "contains_union: {line}");
        assert_eq!(
            a.intersects_union(&b),
            flag(f[6]),
            "intersects_union: {line}"
        );
    }
}

/// `from_begin_end` must match C++ `FromBeginEnd`, and `from_min_max` C++ `FromMinMax`, which
/// is `FromBeginEnd(min, max.next())`.
#[test]
fn from_begin_end_matches_cpp() {
    for line in section_lines("CELLUNION_FROM_BEGIN_END") {
        let f = fields(line);
        let (begin, end) = (CellId(hex64(f[0])), CellId(hex64(f[1])));
        let expected = ids(f[2]);
        assert_eq!(
            CellUnion::from_begin_end(begin, end).cell_ids(),
            &expected[..],
            "from_begin_end: {line}"
        );
        if begin != end {
            assert_eq!(
                CellUnion::from_min_max(begin, end.prev()).cell_ids(),
                &expected[..],
                "from_min_max: {line}"
            );
        }
    }
}

/// The library's own `from_range` (no C++ counterpart) covers the same half-open leaf range
/// as `from_begin_end`, so it must give exactly C++ `FromBeginEnd`'s cells (D-002).
#[test]
#[expect(
    deprecated,
    reason = "checks the deprecated alias against C++ until it is removed"
)]
fn from_range_matches_cpp() {
    for line in section_lines("CELLUNION_FROM_BEGIN_END") {
        let f = fields(line);
        let (begin, end) = (CellId(hex64(f[0])), CellId(hex64(f[1])));
        assert_eq!(
            CellUnion::from_range(begin, end).cell_ids(),
            &ids(f[2])[..],
            "from_range disagrees with C++ FromBeginEnd on: {line}"
        );
    }
}

/// `leaf_cells_covered` must match C++ `LeafCellsCovered` on valid unions, normalised or not.
#[test]
fn leaf_cells_covered_matches_cpp() {
    for line in section_lines("CELLUNION_LEAF_CELLS") {
        let f = fields(line);
        let got = CellUnion::from_verbatim(ids(f[0])).leaf_cells_covered();
        let expected: u64 = f[1].parse().unwrap();
        assert_eq!(
            u64::try_from(got).ok(),
            Some(expected),
            "leaf count: {line}"
        );
    }
}

/// `S2Encode for CellUnion` must write the same bytes as C++ `Encode`.
#[test]
fn encode_matches_cpp() {
    for line in section_lines("CELLUNION_ENCODE") {
        let f = fields(line);
        let mut got = Vec::new();
        CellUnion::from_verbatim(ids(f[0]))
            .encode(&mut got)
            .unwrap();
        assert_eq!(got, bytes(f[1]), "encode: {line}");
    }
}

/// `S2Decode for CellUnion` must keep the ids exactly as encoded, as C++ `Decode` does, for
/// every input C++ decodes to a valid union. Every other input must be an error: either C++
/// rejects it too, or C++ accepts ids that are not a valid union (upstream finding U-003),
/// which the Rust decoder rejects as a documented deviation (FR-017).
#[test]
fn decode_matches_cpp() {
    let (mut accepted, mut rejected_by_both, mut u003) = (0, 0, 0);
    for line in section_lines("CELLUNION_DECODE") {
        let f = fields(line);
        let input = bytes(f[0]);
        let got = CellUnion::decode(&mut &input[..]);
        match (flag(f[1]), flag(f[2])) {
            (true, true) => {
                let got = got.unwrap_or_else(|e| panic!("rejected a valid union ({e}): {line}"));
                assert_eq!(got.cell_ids(), &ids(f[3])[..], "decode: {line}");
                accepted += 1;
            }
            (true, false) => {
                assert!(
                    got.is_err(),
                    "accepted an invalid union (U-003 row): {line}"
                );
                u003 += 1;
            }
            (false, _) => {
                assert!(got.is_err(), "accepted input C++ rejects: {line}");
                rejected_by_both += 1;
            }
        }
    }
    assert!(accepted > 0 && rejected_by_both > 0 && u003 > 0);
}
